#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_case_insensitive() {
        let m = word_counts("Hello, hello world!");
        assert_eq!(m.len(), 2);
        assert_eq!(m["hello"], 2);
        assert_eq!(m["world"], 1);
    }

    #[test]
    fn punctuation_and_digits() {
        let m = word_counts("abc123 -- ABC123; x_y");
        assert_eq!(m["abc123"], 2);
        assert_eq!(m["x"], 1);
        assert_eq!(m["y"], 1);
        assert_eq!(m.len(), 3);
    }

    #[test]
    fn empty() {
        assert!(word_counts("").is_empty());
        assert!(word_counts("!!! ...").is_empty());
        assert_eq!(top_word("?!"), None);
    }

    #[test]
    fn top_word_tie_break() {
        assert_eq!(top_word("b a b a c"), Some(("a".to_string(), 2)));
        assert_eq!(top_word("Zed zed apple"), Some(("zed".to_string(), 2)));
    }
}
